+            case "directed":
+                return new EdgeIcon(End.TAIL, End.ARROW);
+            case "undirected":
+                return new EdgeIcon(End.TAIL, End.TAIL);
+            case "bidirected":
+                return new EdgeIcon(End.ARROW, End.ARROW);
+            case "nondirected":
+                return new EdgeIcon(End.CIRCLE, End.CIRCLE);
